<?phprequire_once __DIR__ . '/../includes/staff_dashboard_access.php';require_once __DIR__ . '/../includes/approval_workflow.php';require_once __DIR__ . '/../includes/approval_integration.php';require_once __DIR__ . '/../includes/approval_center.php';$ctx = bootstrapStaffDashboard(['director general', 'ceo', 'system admin', 'director finance', 'director ict', 'director academics', 'school principal', 'deputy principal', 'hr manager', 'academic registrar', 'school bursar', 'school secretary', 'head nursing', 'head midwifery']);$auth_service = $ctx['auth'];$conn = $ctx['staff'];$studentsConn = $ctx['students'];$websiteConn = $ctx['website'];$user = $ctx['user'];if (function_exists('generateCSRFToken')) { generateCSRFToken(); }$user_id = (int)($user['id'] ?? 0);$role = $_SESSION['role'] ?? '';if (empty($_SESSION['csrf_token'])) {    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));}if ($_SERVER['REQUEST_METHOD'] === 'POST' && $conn) {    $action = $_POST['action'] ?? $_POST['approval_action'] ?? '';    $csrf = $_POST['csrf_token'] ?? $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '';    if (!empty($csrf) && hash_equals($_SESSION['csrf_token'] ?? '', $csrf)) {        $requestId = (int)($_POST['request_id'] ?? 0);        $comment = trim($_POST['comment'] ?? '');        if ($action === 'approve' && $requestId) {            $stmt = $conn->prepare("UPDATE igangaschool_staffs.approval_requests SET status='Approved', approved_by=?, final_approval_at=NOW() WHERE id=? AND status='Active'");            if ($stmt) { $stmt->bind_param('ii', $user_id, $requestId); $stmt->execute(); $stmt->close(); }            $conn->query("INSERT INTO igangaschool_staffs.approval_actions (request_id, action_by, action_type, comment, created_at) VALUES ($requestId, $user_id, 'approve', " . ($comment ? "'" . $conn->real_escape_string($comment) . "'" : "NULL") . ", NOW())");            $_SESSION['success'] = 'Request approved successfully.';        } elseif ($action === 'reject' && $requestId) {            $stmt = $conn->prepare("UPDATE igangaschool_staffs.approval_requests SET status='Rejected', approved_by=?, final_approval_at=NOW() WHERE id=? AND status='Active'");            if ($stmt) { $stmt->bind_param('ii', $user_id, $requestId); $stmt->execute(); $stmt->close(); }            $conn->query("INSERT INTO igangaschool_staffs.approval_actions (request_id, action_by, action_type, comment, created_at) VALUES ($requestId, $user_id, 'reject', " . ($comment ? "'" . $conn->real_escape_string($comment) . "'" : "NULL") . ", NOW())");            $_SESSION['success'] = 'Request rejected.';        } elseif ($action === 'return' && $requestId) {            $conn->query("UPDATE igangaschool_staffs.approval_requests SET status='Active' WHERE id=$requestId");            $conn->query("INSERT INTO igangaschool_staffs.approval_actions (request_id, action_by, action_type, comment, created_at) VALUES ($requestId, $user_id, 'return', " . ($comment ? "'" . $conn->real_escape_string($comment) . "'" : "NULL") . ", NOW())");            $_SESSION['success'] = 'Request returned for revision.';        }    }}$success = $_SESSION['success'] ?? '';$error = $_SESSION['error'] ?? '';unset($_SESSION['success'], $_SESSION['error']);?><!DOCTYPE html><html lang="en"><head><?php include_once __DIR__ . '/../includes/dashboard_head.php'; ?><style>:root { --wf-primary: #1a1a2e; --wf-accent: #0f3460; --wf-gold: #e2b714; --wf-card-bg: #ffffff; --wf-text: #0f172a; --wf-text-muted: #64748b; --wf-border: #e2e8f0; --wf-shadow: 0 1px 3px rgba(0,0,0,0.06); }body { background: #eef1f5; font-family: 'Inter', -apple-system, sans-serif; color: var(--wf-text); font-size: 13px; overflow-x: hidden; }.page-content { padding: 0 !important; }.wf-content { padding: 20px 24px 32px; margin-left: var(--erp-sidebar-width); width: calc(100% - var(--erp-sidebar-width)); background: #f0f2f5; min-height: 100vh; overflow-x: hidden; box-sizing: border-box; }.wf-content .ent-content-area { background: transparent !important; border-radiu